draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // dog body
  ctx.beginPath();
  ctx.arc(W/2 + Math.sin(t) * 50, H/2, 30, 0, 2 * Math.PI);
  ctx.stroke();

  // dog head
  ctx.beginPath();
  ctx.arc(W/2 + Math.sin(t) * 50, H/2 - 50, 20, 0, 2 * Math.PI);
  ctx.stroke();

  // front leg
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t) * 50, H/2 + 30);
  ctx.lineTo(W/2 + Math.sin(t) * 50 - 30, H/2 + 70);
  ctx.stroke();

  // back leg
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t) * 50, H/2 + 30);
  ctx.lineTo(W/2 + Math.sin(t) * 50 + 30, H/2 + 70);
  ctx.stroke();

  // tail
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t) * 50, H/2 + 50);
  ctx.lineTo(W/2 + Math.sin(t) * 50 + Math.cos(t) * 50, H/2 + 100);
  ctx.stroke();

  ctx.restore();
}
